/**
 * TESTS:
 * - encoderMatchesPyTorch: the exported single-image encoder of the Qwen-Image VAE reproduces the PyTorch latent of
 *   its stored reference image
 * - decoderMatchesPyTorch: the exported decoder reproduces the PyTorch image of its stored reference latent
 *
 * The graphs and references are generated by scripts/qwen_image/export_vae.py --size 256 256 into
 * build/models/qwen-image/onnx/ (not in the repository); the tests skip without them.
 **/

#include <gtest/gtest.h>

#include <algorithm>
#include <cmath>
#include <filesystem>
#include <fstream>

#include "klartraum/computegraph/computegraph.hpp"
#include "klartraum/computegraph/tensorelement.hpp"
#include "klartraum/headless_frontend.hpp"
#include "klartraum/onnx/onnx_network.hpp"

using namespace klartraum;

namespace {

const std::string kDirectory = "./build/models/qwen-image/onnx/";

std::vector<float> readFloats(const std::string& path) {
    std::ifstream file(path, std::ios::binary | std::ios::ate);
    std::vector<float> data(static_cast<size_t>(file.tellg()) / sizeof(float));
    file.seekg(0);
    file.read(reinterpret_cast<char*>(data.data()), static_cast<std::streamsize>(data.size() * sizeof(float)));
    return data;
}

// Runs the graph `name` on its stored reference input and returns the maximum absolute and the mean absolute
// difference to its stored reference output, relative to the reference's largest magnitude.
std::pair<float, float> runAgainstReference(const std::string& name, const std::string& inputName,
                                            const std::string& outputName, const std::vector<uint32_t>& inputShape) {
    HeadlessFrontend frontend;
    auto& vc = frontend.getKlartraumEngine().getVulkanContext();
    auto network = vc.create<OnnxNetwork>(kDirectory + name + ".onnx");
    network->retainTensor(outputName);
    auto input = vc.create<TensorElement<float>>(inputShape);
    network->setInputTensor(inputName, input, -1);
    ComputeGraph graph(vc, 1);
    graph.compileFrom(network);
    input->getDataBuffer(0).memcopyFrom(readFloats(kDirectory + name + "_input_f32.bin"));
    graph.submitAndWait(vc.getGraphicsQueue(), 0);

    auto output = std::dynamic_pointer_cast<TensorElement<float>>(network->getOutputElement(outputName));
    EXPECT_NE(output, nullptr);
    if (!output)
        return {INFINITY, INFINITY};
    std::vector<float> actual(output->getDataElementCount());
    output->getDataBuffer(0).memcopyTo(actual);
    const auto expected = readFloats(kDirectory + name + "_output_f32.bin");
    EXPECT_EQ(actual.size(), expected.size());
    float largest = 0.0f, maximum = 0.0f;
    double sum = 0.0;
    for (size_t i = 0; i < std::min(actual.size(), expected.size()); ++i) {
        const float difference = std::abs(actual[i] - expected[i]);
        largest = std::max(largest, std::abs(expected[i]));
        maximum = std::max(maximum, difference);
        sum += difference;
    }
    return {maximum / largest, static_cast<float>(sum / expected.size()) / largest};
}

bool referencesExist(const std::string& name) {
    return std::filesystem::exists(kDirectory + name + ".onnx") &&
           std::filesystem::exists(kDirectory + name + "_input_f32.bin");
}

} // namespace

TEST(QwenImageVaeTest, encoderMatchesPyTorch) {
    if (!referencesExist("vae_encoder_256x256"))
        GTEST_SKIP() << "run scripts/qwen_image/export_vae.py --size 256 256 first";
    const auto [maximum, mean] = runAgainstReference("vae_encoder_256x256", "image", "latent", {1, 3, 256, 256});
    EXPECT_LT(maximum, 1e-3f);
    EXPECT_LT(mean, 1e-4f);
}

TEST(QwenImageVaeTest, decoderMatchesPyTorch) {
    if (!referencesExist("vae_decoder_256x256"))
        GTEST_SKIP() << "run scripts/qwen_image/export_vae.py --size 256 256 first";
    const auto [maximum, mean] = runAgainstReference("vae_decoder_256x256", "latent", "image", {1, 16, 32, 32});
    EXPECT_LT(maximum, 1e-3f);
    EXPECT_LT(mean, 1e-4f);
}
